const $=s=>document.querySelector(s), KEY='paperdesk.v1';
const examples=[
 ['CrossView','Learning Shared Representations Across Views','已读','2025-06','2026-10-15',['多模态','对比学习'],'用跨视角对齐学习共享表示，探索不同模态之间的语义连接。','演示数据集 A','研究问题\n不同模态的表达方式不同，如何让它们在同一个语义空间对齐？\n\n核心方法\n构建跨视角正负样本，通过对比目标学习共享表示。\n\n我的理解\n值得关注的不是模型规模，而是正负样本如何定义。\n\n局限与疑问\n需要进一步检查在缺失模态场景下的表现。'],
 ['Retrieve+','Retrieval-Augmented Reasoning for Knowledge Tasks','在读','2025-09','2026-10-14',['检索增强','推理'],'将外部知识检索融入推理过程，关注证据与回答的一致性。','演示问答集','研究问题\n如何为复杂问答提供可追踪的外部证据？\n\n核心方法\n检索候选段落，再将证据与问题共同输入推理模块。\n\n下一步\n仔细阅读检索误差如何影响最终回答。'],
 ['TinyAdapt','Efficient Adaptation with Compact Updates','已读','2024-11','2026-10-12',['高效微调'],'仅更新少量参数，让预训练模型适配新的下游任务。','演示分类集','核心方法\n冻结主干参数，仅学习小规模增量。\n\n我的理解\n评估时需要同时考虑性能、训练显存与推理延迟。'],
 ['LongContext','Beyond the Window: Modeling Long Documents','待读','2026-02','',['长文本','推理'],'探索长文档中的信息组织，减少上下文长度带来的处理开销。','','阅读计划\n重点关注跨段落信息如何保留，以及评估任务是否包含长距离依赖。'],
 ['DataLens','Understanding the Role of Data Quality','已读','2025-03','2026-10-08',['数据质量'],'从样本质量与分布出发，分析数据选择对模型表现的影响。','演示语料库','研究问题\n增加数据与改善数据质量，哪个更值得优先投入？\n\n我的理解\n关注去重、来源差异和评估集污染的排查。'],
 ['VisionBridge','Bridging Visual Concepts and Language','在读','2025-12','2026-10-06',['多模态'],'通过视觉概念与语言描述的关联，构建可迁移的视觉表征。','演示图文集','核心方法\n利用配对的图像与文本构造监督信号。\n\n局限与疑问\n模型是否依赖文本中出现的背景线索？']
].map((v,i)=>({id:'demo-'+i,title:v[1],alias:v[0],status:v[2],published:v[3],read:v[4],tags:v[5],summary:v[6],datasets:v[7],notes:v[8],results:'',code:'',paper:'',demo:true}));
let papers=[],state={status:'全部文献',tag:'',view:'cards'},editing=null,selected=null;
function notify(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
try{const raw=localStorage.getItem(KEY);papers=raw===null?structuredClone(examples):validate(JSON.parse(raw))}catch(e){papers=structuredClone(examples);setTimeout(()=>notify('无法读取本地数据，已展示示例；请先导出备份再保存。'),500)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function url(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));papers=next;render();return true}catch{notify('保存失败：浏览器存储不可用或空间不足。请导出备份。');return false}}
function validate(data){if(!Array.isArray(data)||data.length>10000)throw Error('格式错误');const ids=new Set();return data.map(p=>{if(!p||typeof p.title!=='string'||!p.title.trim()||typeof p.id!=='string'||ids.has(p.id)||!Array.isArray(p.tags))throw Error('格式错误');ids.add(p.id);const out={};for(const k of ['id','title','alias','published','read','summary','datasets','results','paper','code','notes'])out[k]=typeof p[k]==='string'?p[k]:'';out.status=['待读','在读','已读'].includes(p.status)?p.status:'待读';out.tags=p.tags.filter(x=>typeof x==='string');out.demo=p.demo===true;return out})}
function filtered(){const q=$('#search').value.toLowerCase().trim(),kind=$('#date-kind').value,from=$('#from').value,to=$('#to').value;return papers.filter(p=>{const d=p[kind];const end=d?.length===4?d+'-12-31':d?.length===7?d+'-31':d;const start=d?.length===4?d+'-01-01':d?.length===7?d+'-01':d;return (state.status==='全部文献'||p.status===state.status)&&(!state.tag||p.tags.includes(state.tag))&&(!q||[p.title,p.alias,p.summary,p.notes,p.datasets,...p.tags].join(' ').toLowerCase().includes(q))&&(!from||(d&&end>=from))&&(!to||(d&&start<=to))}).sort((a,b)=>$('#sort').value==='title'?a.title.localeCompare(b.title):(b[$('#sort').value]||'').localeCompare(a[$('#sort').value]||''))}
function status(p){return `<span class="status ${p.status==='在读'?'reading':p.status==='待读'?'todo':''}">${p.status==='已读'?'✓ ':p.status==='在读'?'◐ ':'○ '}${p.status}</span>`}
function render(){const tags=[...new Set(papers.flatMap(p=>p.tags))].sort();$('#nav').innerHTML=['全部文献','在读','待读','已读'].map((s,i)=>`<button class="${state.status===s?'active':''}" data-status="${s}">${['▦','◐','◷','✓'][i]} &nbsp; ${s}<span>${s==='全部文献'?papers.length:papers.filter(p=>p.status===s).length}</span></button>`).join('');$('#tags').innerHTML=tags.map(t=>`<button class="${state.tag===t?'active':''}" data-tag="${esc(t)}"># ${esc(t)}</button>`).join('');$('#crumb').textContent=state.status;$('#stats').innerHTML=[['收藏文献',papers.length,'篇灵感积累'],['正在阅读',papers.filter(p=>p.status==='在读').length,'篇正在探索'],['完成阅读',papers.filter(p=>p.status==='已读').length,'篇已沉淀'],['研究主题',tags.length,'个方向连接']].map(([t,n,h])=>`<div class="stat"><div class="stat-top">${t}</div><div class="stat-num">${String(n).padStart(2,'0')}<small>${h}</small></div></div>`).join('');const list=filtered();$('#count').textContent=`${state.tag?'# '+state.tag+' · ':''}共 ${list.length} 篇文献`;
 $('#demo-label').textContent=papers.some(p=>p.demo)?'DEMO COLLECTION · 含虚构示例，非真实论文':'PERSONAL COLLECTION · 我的文献积累';$('#content').className=state.view==='cards'?'cards':'';
 if(!list.length){$('#content').innerHTML='<div class="empty"><h3>这里还有一页空白</h3><p>新建你的第一篇笔记，或调整搜索与筛选条件。</p><button id="empty-reset">清除筛选</button></div>';return}
 if(state.view==='cards')$('#content').innerHTML=list.map(p=>`<article class="card" data-id="${esc(p.id)}" tabindex="0" role="button" aria-label="打开 ${esc(p.title)}"><div class="card-top"><span class="alias">${esc(p.alias||'Paper')}</span>${status(p)}</div><h3>${esc(p.title)}</h3><p class="summary">${esc(p.summary||'还没有一句话总结，点击记录你的理解。')}</p><div class="chips">${p.tags.map(t=>`<span class="chip">${esc(t)}</span>`).join('')}${p.demo?'<span class="chip">示例</span>':''}</div><div class="card-bottom"><span>◷ ${esc(p.read||'尚未阅读')}</span><span class="${url(p.code)?'has-code':''}">${url(p.code)?'↗ Code':'发表 '+esc(p.published||'待补充')}</span></div></article>`).join('');
 else $('#content').innerHTML='<div class="table-wrap"><table><thead><tr>'+['论文 / 缩写','发表时间','阅读时间','标签','一句话总结','数据集','Code'].map(t=>`<th>${t}</th>`).join('')+'</tr></thead><tbody>'+list.map(p=>`<tr data-id="${esc(p.id)}"><td><b>${esc(p.alias)}</b><br>${esc(p.title)}${p.demo?' · 示例':''}</td><td>${esc(p.published||'—')}</td><td>${esc(p.read||'—')}</td><td>${esc(p.tags.join(' / '))}</td><td>${esc(p.summary||'—')}</td><td>${esc(p.datasets||'—')}</td><td>${url(p.code)?`<a href="${esc(url(p.code))}" target="_blank" rel="noopener">打开 ↗</a>`:'—'}</td></tr>`).join('')+'</tbody></table></div>';
}
function reset(){state.tag='';state.status='全部文献';$('#search').value='';$('#from').value='';$('#to').value='';render()}
function openEditor(p){editing=p?.id||null;$('#form').reset();$('#edit-title').textContent=p?'编辑文献笔记':'新建文献笔记';for(const el of $('#form').elements)if(el.name)el.value=p?(el.name==='tags'?p.tags.join(', '):p[el.name]||''):el.name==='status'?'待读':el.name==='read'?new Date().toLocaleDateString('en-CA'):'';$('#editor').showModal()}
function showDetail(id){const p=papers.find(x=>x.id===id);if(!p)return;selected=id;$('#detail-body').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">${esc(p.alias||'PAPER NOTE')}${p.demo?' / 虚构示例':''}</div><h2>${esc(p.title)}</h2></div><button class="close" data-close="detail" aria-label="关闭">×</button></div><div class="detail-meta">${status(p)}<span>发表 ${esc(p.published||'未填写')}</span><span>阅读 ${esc(p.read||'未填写')}</span></div><div class="chips">${p.tags.map(t=>`<span class="chip"># ${esc(t)}</span>`).join('')}</div><div class="callout">${esc(p.summary||'尚未填写一句话总结')}</div><div class="detail-data">数据集：${esc(p.datasets||'待补充')}<br>关键结果：${esc(p.results||'待补充')}</div><div class="detail-links">${url(p.paper)?`<a href="${esc(url(p.paper))}" target="_blank" rel="noopener">论文原文 ↗</a>`:''}${url(p.code)?`<a href="${esc(url(p.code))}" target="_blank" rel="noopener">Code ↗</a>`:''}</div><h3>阅读笔记</h3><div class="note-body">${esc(p.notes||'还没有笔记，开始记录你的想法吧。')}</div><div class="form-actions"><button class="danger" id="delete">删除笔记</button><button id="markdown">↓ 导出 Markdown</button><button class="primary" id="edit">编辑笔记</button></div>`;$('#detail').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.close)$('#'+b.dataset.close).close();if(b?.dataset.status){state.status=b.dataset.status;render()}if(b?.dataset.tag){state.tag=state.tag===b.dataset.tag?'':b.dataset.tag;render()}if(b?.dataset.view){state.view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));render()}if(e.target.closest('a'))return;const card=e.target.closest('[data-id]');if(card)showDetail(card.dataset.id);if(b?.id==='empty-reset')reset();if(b?.id==='edit'){$('#detail').close();openEditor(papers.find(p=>p.id===selected))}if(b?.id==='delete'&&confirm('确定删除这篇笔记？建议先导出备份。')){if(persist(papers.filter(p=>p.id!==selected))){$('#detail').close();notify('笔记已删除')}}if(b?.id==='markdown'){const p=papers.find(p=>p.id===selected);download((p.alias||'paper')+'.md','---\n'+['id','title','alias','published','read','status','tags','summary','datasets','results','paper','code'].map(k=>k+': '+JSON.stringify(p[k]??'')).join('\n')+'\n---\n\n'+p.notes,'text/markdown')}});
document.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('.card')){e.preventDefault();showDetail(e.target.dataset.id)}});
$('#new').onclick=()=>openEditor();$('#search').oninput=render;for(const id of ['sort','date-kind','from','to'])$('#'+id).onchange=render;$('#filter-toggle').onclick=()=>{$('#date-filters').hidden=!$('#date-filters').hidden};$('#reset').onclick=reset;
$('#form').onsubmit=e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));p.title=p.title.trim();if(!p.title){notify('请填写论文标题');return}for(const k of ['code','paper'])if(p[k]&&!url(p[k])){notify('链接仅支持 http 或 https');return}if(p.published){const parts=p.published.split('-').map(Number);if((parts[1]&&(parts[1]<1||parts[1]>12))||(parts.length>1&&!parts[1])||(parts.length===3&&(parts[2]<1||parts[2]>new Date(parts[0],parts[1],0).getDate()))){notify('请填写有效的发表日期');return}}p.tags=[...new Set(p.tags.split(/[,，、]/).map(t=>t.trim()).filter(Boolean))];p.id=editing||crypto.randomUUID();p.demo=editing?papers.find(x=>x.id===editing)?.demo===true:false;const next=editing?papers.map(x=>x.id===editing?p:x):[p,...papers];if(persist(next)){$('#editor').close();notify('笔记已保存，概览已自动更新')}};
function download(name,body,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type:type+';charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function csvCell(s){s=String(s??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
$('#csv').onclick=()=>{const rows=filtered().map(p=>[p.title,p.alias,p.published,p.read,p.status,p.tags.join('; '),p.summary,p.datasets,p.results,p.paper,p.code,p.demo?'虚构示例':'']);download('文献概览.csv','\ufeff'+[['论文标题','缩写','发表时间','阅读时间','状态','标签','一句话总结','数据集','关键结果','论文链接','Code','备注'],...rows].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv');notify(`已导出当前筛选的 ${rows.length} 篇文献`)};
$('#backup').onclick=()=>download('paperdesk-backup.json',JSON.stringify(papers,null,2),'application/json');$('#restore').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>20000000)throw Error();const next=validate(JSON.parse(await f.text()));if(confirm(`将用备份中的 ${next.length} 篇笔记替换当前文献库，是否继续？`)){if(persist(next))notify('备份导入成功')}}catch{notify('导入失败：请选择有效的 Paperdesk JSON 备份')}finally{e.target.value=''}};
render();
